private const val MOD = 1_000_000_007L

fun main() {
    val input = FastScanner()
    val n = input.nextInt()
    val m = input.nextInt()
    val k = input.nextInt()

    val dp = Array(2020) { LongArray(2020) }

    for (i in 0 until maxOf(n, m)) {
        for (j in 0..i) {
            dp[j][i] = if (j > 0) {
                (dp[j][i - 1] + dp[j - 1][i - 1]) % MOD
            } else {
                1L
            }
        }
    }

    println(dp[2 * k][n - 1] * dp[2 * k][m - 1] % MOD)
}

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c = readByte()
        while (c <= 32 && c != -1) c = readByte()

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var result = 0
        while (c > 32 && c != -1) {
            result = result * 10 + c - '0'.code
            c = readByte()
        }
        return result * sign
    }
}

